import { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { MODE_SOURCE, PRO_MODES, SPEED_SECONDS, type ModeId } from '@lexpad/core';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { proHere, useBilling } from '@/features/billing/state.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { learnShows } from '@/features/learn/state.js';
import { modePath, shownModes } from './data.js';
import { useOpenModes } from './useOpenModes.js';
import styles from './ModesSection.module.css';

/** The four that get a card of their own (spec 6.9); the rest are a row of chips under them. */
const CARDS: readonly ModeId[] = ['match', 'speed', 'dictation', 'builder'];

/** The address fragment Today's "Games and drills" tile opens Decks at. */
export const GAMES_ANCHOR = 'games';

const ICONS: Record<ModeId, IconName> = {
  match: 'grid',
  speed: 'flame',
  dictation: 'headphones',
  builder: 'shuffle',
  collocation: 'cards',
  sayIt: 'mic',
  sentence: 'pencil',
};

/**
 * "Games and drills" on the Decks screen (SRS v2 phase E). Only the modes
 * switched on for this account appear, and only those the notebook can feed
 * (Dictation also needs a voice for its language). With none, the section
 * is not drawn at all, so the screen is what it was. The modes themselves
 * are separate chunks, fetched when one is opened.
 */
export function ModesSection(): React.JSX.Element | null {
  const navigate = useNavigate();
  const { hash } = useLocation();
  const { view, open } = useOpenModes();
  const lang = view.notebook?.targetLang ?? 'en';
  const meaningLang = view.notebook?.meaningLang ?? 'en';
  const billing = useBilling((state) => state.state);
  const ensure = useBilling((state) => state.ensure);
  const hasPro = shownModes(view.srs).some((mode) => PRO_MODES.has(mode));
  useEffect(() => {
    if (hasPro) ensure();
  }, [ensure, hasPro]);
  // Opened from Today's "Games and drills" tile: the section is the reason
  // for the visit, so it comes into view once it is drawn (SRS v2).
  const section = useRef<HTMLElement | null>(null);
  const drawn = open.length > 0;
  useEffect(() => {
    if (!drawn || hash !== `#${GAMES_ANCHOR}`) return;
    section.current?.scrollIntoView({ block: 'nearest' });
  }, [drawn, hash]);

  if (!drawn) return null;
  // Pro is marked only where it is not already open here: a paid account,
  // or a notebook Lexpad never charges for, sees no mark at all.
  const locked = (mode: ModeId): boolean => PRO_MODES.has(mode) && !proHere(billing, lang, meaningLang);
  // The new learner's journey (M7): each one says before the tap whether
  // its answers move a word's box, which used to be learnt only inside it.
  const tagged = learnShows(view.srs);
  const cards = open.filter((mode) => CARDS.includes(mode));
  const chips = open.filter((mode) => !CARDS.includes(mode));

  return (
    <section ref={section} id={GAMES_ANCHOR} className={styles.section} aria-labelledby="modes-title">
      <h2 id="modes-title" className={styles.title}>
        {t('modes.title')}
      </h2>
      {cards.length > 0 && (
        <div className={styles.grid}>
          {cards.map((mode) => (
            <button
              key={mode}
              type="button"
              className={styles.card}
              onClick={() => {
                void navigate(modePath(mode));
              }}
            >
              <span className={styles.icon} aria-hidden="true">
                <Icon name={ICONS[mode]} size={20} weight={1.9} />
              </span>
              <span className={styles.name}>{t(`modes.${mode}`)}</span>
              <span className={styles.note}>{noteOf(mode)}</span>
              {tagged && (
                <span className={styles.tagRow}>
                  <Tag mode={mode} />
                </span>
              )}
            </button>
          ))}
        </div>
      )}
      {chips.length > 0 && (
        <div className={styles.chips} role="group" aria-label={t('modes.more')}>
          {chips.map((mode) => (
            <button
              key={mode}
              type="button"
              className={styles.chip}
              onClick={() => {
                void navigate(modePath(mode));
              }}
            >
              <Icon name={ICONS[mode]} size={16} weight={1.9} />
              <span>{t(`modes.${mode}`)}</span>
              {locked(mode) ? (
                <span className={styles.pro}>{t('modes.pro')}</span>
              ) : (
                tagged && <Tag mode={mode} />
              )}
            </button>
          ))}
        </div>
      )}
    </section>
  );
}

/** "Moves boxes" for a drill that counts like spelling, "Practice only" for a game. */
function Tag({ mode }: { mode: ModeId }): React.JSX.Element {
  const counts = MODE_SOURCE[mode] === 'session';
  return (
    <span className={cx(styles.tag, counts ? styles.tagCounts : styles.tagPractice)}>
      {t(counts ? 'modes.tagCounts' : 'modes.tagPractice')}
    </span>
  );
}

function noteOf(mode: ModeId): string {
  switch (mode) {
    case 'match':
      return t('modes.matchNote');
    case 'speed':
      return t('modes.speedNote', { seconds: SPEED_SECONDS });
    case 'dictation':
      return t('modes.dictationNote');
    default:
      return t('modes.builderNote');
  }
}
