import type { ModeId } from '@lexpad/core';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { MODES_LOADING, canFeed, loadModes, shownModes, type ModesView } from './data.js';
import { useCanListen } from './useCanListen.js';

/**
 * The games and drills this notebook and this device can run right now:
 * switched on for the account (`shown`), fed by the notebook (`canFeed`),
 * with a voice for Dictation and a recogniser for Say it. Decks draws them
 * and Today counts them, from the same answer, so the two never disagree.
 *
 * With every mode switched off (the flag off, or a server without SRS v2)
 * nothing is read beyond the flag: `loadModes` skips the words.
 */
export function useOpenModes(): { view: ModesView; open: ModeId[] } {
  const now = useCurrentDay();
  // An async querier, so Dexie follows every read past the first await.
  const view = useLiveQuery(async () => loadModes(now), MODES_LOADING, [now]);
  const lang = view.notebook?.targetLang ?? 'en';
  const canSpeak = useCanSpeak(lang);
  const shown = shownModes(view.srs);
  // Say it is offered only where the device can listen; asked once, and only when it is switched on.
  const canListen = useCanListen(shown.includes('sayIt'));
  if (!view.ready || view.notebook === undefined) return { view, open: [] };
  const open = shown.filter(
    (mode) =>
      canFeed(mode, view.words, lang) &&
      (mode !== 'dictation' || canSpeak) &&
      (mode !== 'sayIt' || canListen === true),
  );
  return { view, open };
}
